SELECT round(avg(precio)) AS promedio FROM productos;

SELECT sku, nombre, precio,
       precio - (SELECT round(avg(precio)) FROM productos) AS sobre_promedio
FROM productos
WHERE precio > (SELECT avg(precio) FROM productos)
ORDER BY precio DESC, sku;

WITH nombre1 [(columna, …)] AS [ [ NOT ] MATERIALIZED ] (
       consulta1
     ),
     nombre2 AS (
       consulta2          -- puede usar nombre1
     )
SELECT …                  -- puede usar nombre1 y nombre2
FROM nombre1 JOIN nombre2 …;

WITH caros AS (
  SELECT * FROM productos WHERE precio > 100000
)
SELECT count(*) FROM caros;

SELECT count(*) FROM caros;

WITH resumen AS (SELECT count(*) AS n FROM base),
     base    AS (SELECT * FROM productos WHERE activo)
SELECT n FROM resumen;

EXPLAIN (COSTS OFF)
WITH p AS (SELECT * FROM pedidos)
SELECT * FROM p WHERE id = 42;

EXPLAIN (COSTS OFF)
