WITH RECURSIVE nombre (columnas) AS (
    término ancla          -- no se refiere a «nombre»: el punto de partida
  UNION ALL                -- o UNION, que descarta filas repetidas
    término recursivo      -- se refiere a «nombre» una sola vez
)
SELECT … FROM nombre;

SELECT count(*) AS a_mover
FROM prestamos
WHERE fecha_devolucion < '2025-04-01';

WITH movidos AS (
  DELETE FROM prestamos
  WHERE fecha_devolucion < '2025-04-01'
  RETURNING *
)
INSERT INTO prestamos_historicos
SELECT * FROM movidos;

SELECT (SELECT count(*) FROM prestamos)            AS prestamos,
       (SELECT count(*) FROM prestamos_historicos) AS historicos;

WITH movidos AS (
  DELETE FROM prestamos
  WHERE fecha_prestamo < '2025-04-01'
  RETURNING *
)
