SELECT * FROM movidos;

SELECT count(*) AS siguen_en_prestamos FROM prestamos;

-- 1) Dos cambios a la misma fila en una sola sentencia
SELECT sueldo AS antes FROM empleados WHERE id = 2;

WITH a AS (
  UPDATE empleados SET sueldo = sueldo + 1000
  WHERE id = 2
  RETURNING sueldo
)
UPDATE empleados SET sueldo = sueldo + 1
WHERE id = 2;

SELECT sueldo AS despues FROM empleados WHERE id = 2;

-- 2) Un WITH que modifica datos debe ir en el nivel superior
SELECT *
FROM (WITH x AS (DELETE FROM asignaciones RETURNING *)
      SELECT * FROM x) AS s;

